INSERT INTO `authors` VALUES (1,'Карлос Кастанеда',NULL,NULL,'Американский писатель и антрополог.','2026-10-22 20:20:18','2026-10-22 20:20:18'),(2,'Говард Лавкрафт',NULL,NULL,'Американский писатель, создатель мифов Ктулху.','2026-10-22 20:20:18','2026-10-22 20:20:18'),(3,'Филип К. Дик',NULL,NULL,'Американский писатель-фантаст.','2026-10-22 20:20:18','2026-10-22 20:20:18'),(4,'Пушкин',NULL,NULL,'Русский писатель','2026-11-06 18:25:01','2026-11-06 18:25:01'),(5,'Долин А. А.',NULL,NULL,'','2026-11-14 20:23:30','2026-11-25 22:41:38'),(6,'Попов Г. В.',NULL,NULL,'','2026-11-14 20:23:57','2026-11-25 22:41:27'),(7,'Альфред Бестер',1913,1987,'Альфред Бестер (18 декабря 1913 — 30 сентября 1987) — американский писатель-фантаст, редактор и журналист, классик научной фантастики.\r\nОсновные факты\r\n• Даты жизни: родился 18 декабря 1913 года в Нью-Йорке, умер 30 сентября 1987 года в Дойлстауне (штат Пенсильвания).\r\n• Деятельность: писатель-фантаст, редактор (в том числе журнала Holiday с конца 1950-х годов), журналист. Дебютировал рассказом The Broken Axiom в 1939 году.\r\n• Псевдонимы: Сонни Пауэлл (Sonny Powell), Александр Блейд (Alexander Blade), Джон Леннокс (John Lennox).\r\n• Главные романы: The Demolished Man («Человек без лица», 1952/1953) и Tiger! Tiger! / The Stars My Destination («Тигр! Тигр!» / «Моя цель — звёзды», 1956).\r\n• Награды и признание: лауреат премии «Хьюго» (1953) и звания «Гранд-мастер» премии «Небьюла» (1987); включён в Зал славы премии «Прометей» (1988) и Зал славы научной фантастики (2001).','2026-11-24 22:24:32','2026-11-24 22:24:32'),(8,'Роберт Шекли',1928,2005,'Роберт Шекли (1928–2005) — американский писатель-фантаст, прославившийся ироничными, сатирическими и абсурдистскими рассказами и романами. Он автор сотен рассказов и повестей, а также около двух десятков романов.\r\n\r\nО творчестве и стиле\r\n\r\n• Жанр и тон: сатира, чёрный юмор, парадоксальные сюжеты и доведение привычных социальных или технических идей до абсурда.\r\n• Популярность: был широко известен и популярен в СССР и на постсоветском пространстве; неоднократно бывал в Москве и Киеве.\r\n• Дети: Алиса Квитни, Аня Шекли, Джейсон Шекли, Джед Шекли.\r\n\r\nИзвестные произведения\r\n\r\n• Романы и повести: «Обмен разумов», «Цивилизация Статуса», «Координаты чудес», «Корпорация „Бессмертие“», «Билет на планету Транай».\r\n• Рассказы: «Страж-птица», «Седьмая жертва», «Премия за риск».','2026-11-24 22:30:17','2026-11-24 22:30:17'),(9,'Виктор Санчес',1961,NULL,'Виктор Санчес (род. 9 декабря 1961 года) — мексиканский писатель и исследователь коренных традиций, шаманизма и личного развития. В раннем творчестве его вдохновляли труды Карлоса Кастанеды, а также исследования среди вирарика (уичолей) и потомков тольтеков. Он также ввёл термин «анти-антропология».','2026-11-24 22:37:27','2026-11-24 22:39:10'),(10,'Кокачев А. В.',NULL,NULL,'Александр Витальевич Кокачев — детский писатель и художник-иллюстратор из Республики Коми.\r\n\r\nОсновные факты и творчество\r\n\r\n• Тематика книг. Автор пишет природоведческие произведения, сказки и рассказы о северной природе и жизни детей.\r\n• Известные издания. Наиболее известная его книга — «Ухрюмон», изданная в Сыктывкаре в 1995 году.\r\n• Роль в культуре региона. Произведения А. В. Кокачева включены в школьные программы и курсы по литературному чтению в Республике Коми.','2026-11-24 22:45:32','2026-11-25 22:41:14'),(11,'Евтифьев М. Д.',NULL,NULL,'Михаил Дмитриевич Евтифьев — российский писатель и историк авиации и ракетной техники.','2026-11-24 22:58:49','2026-11-25 22:41:03'),(12,'Шумилин А. А.',NULL,NULL,'','2026-11-24 23:36:20','2026-11-25 22:40:51'),(13,'Беляев Александр Романович',1884,1942,'русский писатель-фантаст, один из основоположников советской научно-фантастической литературы. Среди наиболее известных его романов: «Голова профессора Доуэля», «Человек-амфибия», «Ариэль», «Звезда КЭЦ» и многие другие (всего более 70 научно-фантастических произведений, в том числе 13 романов). За значительный вклад в русскую фантастику и провидческие идеи Беляева называют «русским Жюлем Верном»','2026-11-25 22:40:33','2026-11-25 22:43:21'),(14,'Неизвестный автор',NULL,NULL,'','2026-11-25 22:49:42','2026-11-25 22:49:42'),(15,'Бажов, Павел Петрович',1879,1950,'Павел Петрович Бажов (15 [27] января 1879 — 3 декабря 1950) — русский и советский писатель, фольклорист, публицист и журналист, получивший всемирную известность как автор уральских сказов.\r\n\r\nОсновные вехи биографии\r\n\r\n• Происхождение и образование. Родился в семье горнозаводского мастера в посёлке Сысертский Завод (ныне город Сысерть Свердловской области). Окончил Екатеринбургское духовное училище и Пермскую духовную семинарию, но от карьеры священника отказался, выбрав работу учителя.\r\n• Педагогика и журналистика. Более пятнадцати лет преподавал русский язык в Екатеринбурге и Камышлове, в годы Гражданской войны воевал на стороне красных и занимался подпольной работой, а в 1920-х годах перешёл в журналистику и краеведение.\r\n• Поздняя литературная слава. Первую книгу очерков «Уральские были» выпустил в 1924 году, но настоящая слава пришла к писателю после 60 лет — с выходом в 1939 году первого издания сборника «Малахитовая шкатулка».\r\n• Общественное признание. В 1943 году за «Малахитовую шкатулку» получил Сталинскую премию второй степени, в 1944 году был награждён орденом Ленина, а также избирался депутатом Верховного Совета СССР.\r\n\r\nОсобенности творчества и главные произведения\r\n\r\nБажов создал в русской литературе уникальный жанр литературного сказа, объединив устные предания уральских горнорабочих и старателей с живым народным языком и авторской фантазией.\r\n• «Малахитовая шкатулка» (1939). Главный труд жизни писателя, который он пополнял новыми текстами до самой смерти.\r\n• «Медной горы Хозяйка» (1936). Сказ о загадочной хранительнице подземных богатств и горном мастере Степане.\r\n• «Каменный цветок» (1938). История талантливого камнереза Данилы-мастера, стремившегося постичь тайну живой красоты камня.\r\n• «Серебряное копытце» (1938). Зимняя история о старом охотнике Коковане, сиротке Дарёнке и волшебном козлике, выбивающем самоцветы.\r\n• Другие известные сказы. «Огневушка-Поскакушка», «Синюшкин колодец», «Золотой Волос», «Хрупкая веточка», «Горный мастер».\r\n\r\nНаследие\r\n\r\nПроизведения Бажова переведены на десятки языков мира и легли в основу множества экранизаций, мультфильмов, театральных постановок, опер и балетов (включая балет Сергея Прокофьева «Сказ о каменном цветке»). Подробнее о жизни и архивах писателя можно узнать в статье о Павле Петровиче Бажове на Википедии.\r\n','2026-11-26 22:38:11','2026-11-26 22:39:03'),(16,'Александр Владимирович Тюрин',NULL,NULL,'','2026-11-26 22:50:25','2026-11-26 22:50:25'),(17,'Александр Геннадьевич Щёголев',NULL,NULL,'','2026-11-26 22:50:47','2026-11-26 22:50:47'),(18,'Валерий Михайлович Приёмыхов',NULL,NULL,'','2026-11-26 22:50:59','2026-11-26 22:50:59'),(19,'Константин Васильев',NULL,NULL,'','2026-11-26 22:51:26','2026-11-26 22:51:26'),(20,'Елена Всеволодовна Перехвальская',NULL,NULL,'','2026-11-26 22:51:38','2026-11-26 22:51:38'),(21,'Юрий Марксович Коротков',NULL,NULL,'','2026-11-26 22:51:52','2026-11-26 22:51:52'),(22,'Романов В.',NULL,NULL,'','2026-11-26 22:52:11','2026-11-26 22:52:11'),(23,'Елена Васильевна Габова',NULL,NULL,'','2026-11-26 22:52:25','2026-11-26 22:52:25'),(24,'Андрей Петрович Ефремов',NULL,NULL,'','2026-11-26 22:52:38','2026-11-26 22:52:38'),(25,'Светлана Иванова',NULL,NULL,'','2026-11-26 22:52:49','2026-11-26 22:52:49'),(26,'Вальтер Шелленберг',1910,1952,'Ва́льтер Фри́дрих Ше́лленберг (нем. Walter Friedrich Schellenberg, 16 января 1910, Саарбрюккен, Германская империя — 31 марта 1952, Турин, Италия) — начальник внешней разведки службы безопасности (SD-Ausland — VI отдел РСХА), бригадефюрер СС. Член НСДАП с 1933 года.','2026-11-26 23:06:37','2026-11-26 23:06:37');
