INSERT INTO `books` VALUES (7,'Кэмпо - традиция воинских искусств',1990,'В книге на широком историческом и этнографическом материале прослеживается становление и развитие различных школ воинских искусств в Китае и Японии с древности до наших дней. Кэмпо как разветвленный, многонациональный комплекс воинских искусств исследуется в свете даосских натурфилосовских построений и буддийской метафизики, с одной стороны и как вополщение конфуцианских этических норм - с другой. Особенно важное место в повествовании занимают популярные ныне школы борьбы без оружия (и частично с оружием) стран Восточно-азиатского культурного региона - у-шу, карате, дзю-до, айки-до и систем психофизического тренинга (школа Шаолиньского монастыря, обучение лазутчиков ниндзя, воспитания самураев и т.п.). Цветные иллюстрации на отдельных листах, ч/б рисунки по тексту.',1,2,NULL,'hardcover',429,50000,'5-02-016966-8','2026-11-14 20:33:32','2026-11-24 22:08:39'),(8,'Американская фантастика',1989,'В сборник включены произведения известных американских писателей-фантастов: Альфреда Бестера (\"Тигр! Тигр!\") и Роберта Шекли (\"Седьмая жертва\").',1,3,NULL,'paperback',192,200000,'5-255-00192-9','2026-11-24 22:22:03','2026-11-24 22:31:42'),(9,'Учение дона Карлоса. Практическое использование техник Карлоса Кастанеды',1995,'Эта книга - открытая дверь в мир магии, она позволит Вам приобрести уникальный опыт магического восприятия мира и применить на практике техники Карлоса Кастанеды.\r\n\r\nМиллионы читателей книг Карлоса Кастанеды на протяжении многих лет с восхищением читали описания техник дона Хуана. Теперь появилась возможность освоить некоторые из них на практике.',5,4,NULL,'paperback',240,4000,'5-86894-054-7','2026-11-24 22:37:06','2026-11-24 23:52:20'),(10,'Автолет, подаренный Уррой',1997,'«Автолет, подаренный Уррой» — фантастико-приключенческая книга для детей среднего школьного возраста, написанная автором Александром Витальевичем Кокачевым.',2,5,NULL,'paperback',144,20000,'5-256-01396-3','2026-11-24 22:49:50','2026-11-24 22:49:50'),(11,'Штурм неба. Вехи истории реактивной авиации',2006,'В книге рассказывается о становлении реактивной авиации Германии, СССР, Великобритании, США, Франции, Италии, Чехословакии и Японии в 1928-1946 гг. В этот период усилиями выдающихся ученых и конструкторов разрабатывались первые реактивные двигатели, испытывались первые реактивные самолеты. Сильнейший импульс в своем развитии реактивная авиация получила во время Второй мировой войны. С 1939 по 1945 г. немецкие авиаконструкторы создали и поставили в серийное производство несколько лучших для своего времени самолетов, оказавших в дальнейшем большое влияние на развитие реактивной авиации многих стран.\r\n\r\nКнига будет интересна не только специалистам, но и всем любителям истории авиации.',2,6,NULL,'hardcover',544,3000,'5-9533-1144-3','2026-11-24 22:55:00','2026-11-24 23:01:41'),(12,'Авиационно-космические системы США. История, современность, перспективы',2005,'В книге дается описание основных программ, выполняемых в США с целью создания новых средств выведения на орбиту космических аппаратов. Помимо традиционных ракет-носителей особое внимание уделяется авиационно-космическим системам многоразового использования и перспективным гиперзвуковым летательным аппаратам. Кроме того, в издании представлен ретроспективный обзор полувековой эволюции проектов воздушно-космических самолетов и эксплуатирующихся в настоящее время семейств одноразовых ракет-носителей. Отдельный раздел посвящен истории и современному состоянию американских космодромов. Книга рассчитана на читателей, интересующихся авиационно-космической тематикой, студентов вузов и специалистов аэрокосмической отрасли.',2,6,NULL,'hardcover',528,5000,'5-9533-0820-5','2026-11-24 23:34:47','2026-11-24 23:36:41'),(13,'Египетская книга мертвых',2017,'«Египетская книга мертвых» давно уже для многих из нас стала символом Египта в не меньшей степени, чем пирамиды, фараоны, мумии и Сфинкс. Эта древнейшая книга на протяжении почти 5000 лет занимала важное место в жизни каждого благочестивого египтянина: будь то фараон или пахарь, супруга фараона или ее служанка — все они жили, постоянно обращаясь к учению «Книги мертвых»; египтян хоронили, руководствуясь ее указаниями; их надежда на вечную жизнь и счастье была основана на действенности ее гимнов, молитв и заклинаний. Для них главы «Книги мертвых» были всемогущим путеводителем по дороге, которая через смерть и погребение вела в царство света и жизни, в присутствие божественного Осириса, смерть превозмогшего, который одарил мужчин и женщин способностью «родиться вновь». А потому прочтение великой и мудрой книги может помочь всем интересующимся историей древних цивилизаций понять и почувствовать, чем жил и дышал Древний Египет.',4,7,1,'paperback',528,4000,'978-5-389-13760-8','2026-11-24 23:40:41','2026-11-25 22:50:04'),(14,'Фантастика',1987,'В книгу известного писателя-фантаста А.Р.Беляева входят широкоизвестные романы: \"Голова профессора Доуэля\",\"Человек-амфибия\", \"Прыжок в ничто\" и рассказ \"Мистер смех\"',1,8,NULL,'hardcover',576,80000,'5-7555-0009-6','2026-11-25 22:47:07','2026-11-25 22:48:46'),(15,'Уральские сказы',1993,'В сборник «Уральские сказы» вошли самые известные произведения замечательного русского писателя Павла Петровича Бажова, написанные на основе фольклора уральских горнорабочих и старателей. На страницах книги оживают древние легенды о подземных богатствах и загадочных хранителях недр — суровой и справедливой Хозяйке Медной горы, могучем Великом Полозе, озорной Огневушке-Поскакушке и коварной бабке Синюшке. Это глубокие, поэтичные истории о талантливых камнерезах и рудознатцах, о бескорыстии, верности своему слову и подлинном искусстве, которое открывается только тем, кто вкладывает в труд чистую душу.',2,9,NULL,'hardcover',336,70000,'5-85311-006-3','2026-11-26 22:45:13','2026-11-26 22:46:27'),(16,'Я летаю во сне',1991,'Герои повестей современных молодых писателей, школьники, впервые серьезно постигающие жизнь, получают нравственные уроки, вырабатывают свои критерии и активную гражданскую позицию. Это повести о школьной жизни ребят, о настоящей дружбе, о первой любви',1,10,NULL,'hardcover',366,100000,'5-08-001578-0','2026-11-26 23:02:38','2026-11-26 23:02:38'),(17,'Мемуары',1991,'Впервые на русском языке публикуются воспоминания руководителя зарубежной разведки нацистской Германии Вальтера Шелленберга. Автор излагает историюсозданияполитической разведк, развития Главного имперского управления безопасности, в систему которого входило и ведомство, возглавлявшееся Шелленбергом, характеризует крупнейшие разведывательные операции немцев во время второй мировой войны.',NULL,11,NULL,'hardcover',352,58000,'5-7042-7009-1','2026-11-26 23:20:33','2026-11-26 23:21:04');
