INSERT INTO `publishers` VALUES (1,'Художественная литература','Художественная литература — издательство Государственного комитета Совета Министров СССР по делам издательств, полиграфии и книжной торговли. Крупнейшее и в некотором смысле старейшее литературное издательство советских времен. Его история восходит к «Государственному издательству РСФСР» (Госиздату) — первому крупному советскому издательству, которое было создано в 1919 году по инициативе А.В.Луначарского. На базе его литературно-художественного сектора в 1930 г. было создано Государственное издательство художественной литературы (ГИХЛ), которое с 1934 года стало называться Гослитиздатом, а с 1963 г. — «Художественная литература».\r\n\r\nНеобходимо заметить, что, не смотря на переименование издательства в 1963-1965 годах (особенно при издании ранее начатых собраний сочинений, на титуле продолжала фигурировать название «Государственное издательство художественной литературы»\r\n\r\nЦентральное отделение издательства находилось в Москве\r\n\r\nВыписка с сайта Российской книжной палаты:\r\n978-5-280 — Ордена Трудового Красного Знамени издательство «Художественная литература» — Государственное унитарное предприятие. — (М.: Художественная литература)\r\n107882, Москва, Нов. Басманная, д. 19, стр. 1, ГУП издательство «Художественная литература»\r\n\r\nКолесников С.Г. — Директор тел. 261-88-24 факс 261-79-54\r\n\r\nимелось также отделение в Ленинграде, но своего ISBN-префикса оно не имело.\r\n\r\nИздания, подготовленные отделениями совместно (то есть в том случае, если на титуле стоят оба города — Москва и Ленинград), смотри на этой странице.\r\n\r\nВ 1967-1977 годах издательством было осуществлено уникальное издание — «Библиотека всемирной литературы», с 1977 оно выпускало многотомную «Библиотеку классики». Этим издательством издавались многие популярные журналы советских времен — «Роман-газета», «Москва», «Нева», «Детская литература» и другие.\r\n\r\nВ 1980 г. издательство награждено орденов Трудового Красного Знамени.\r\n\r\nДокументы, связанные с историей издательства, хранятся в Российском государственном архиве литературы и искусства (РГАЛИ). Ф. 613. (см.: http://guides.rusarchives.ru/node/27291 )\r\n\r\nС 21 октября 2010 года на основании распоряжение Правительства Российской Федерации № 1822-р «Об утверждении перечня федеральных государственных унитарных предприятий, находящихся в ведении Роспечати» приобрело статус — Федеральное государственное унитарное предприятие.\r\n\r\nВ 1990-х годах возникло какое-то АО «Издательство «Всемирная литература» (Адрес: 191186 СПб., Невский пр-т, 28. ЛР № 070801 от 28.12.92).','2026-11-14 00:14:36','2026-11-14 00:14:36'),(2,'Наука','\"Наука\" – старейшее научное издательство России и одно из крупнейших в мире – ведет отсчет своей истории с 1727 г., когда была открыта Академическая типография как издательский орган Академии наук. В настоящее время в составе Издательства находятся три действующих полиграфических предприятия. У издательства имеется своя книгораспространительская сеть – \"Академкнига\".','2026-11-14 20:26:00','2026-11-14 20:26:00'),(3,'Профиздат','Профиздат (Информационно-издательский дом «Профиздат») — советское и российское издательство, основанное в 1930 году (на базе издательской деятельности профсоюзов, ведущей отсчёт с 1918 года).','2026-11-24 22:21:52','2026-11-24 22:21:52'),(4,'Ось-89','«Ось-89» — российское издательство из Москвы, специализирующееся на учебно-методической, деловой и развивающей литературе.\r\n\r\nОсновные направления\r\n\r\n• Психология и педагогика: учебно-методические пособия и практические материалы.\r\n• Детская литература: развивающие книги и пособия.\r\n• Бизнес, экономика и финансы: справочники, аналитика и практические руководства (включая темы делового имиджа и бизнес-разведки).\r\n• Нормативно-правовая литература: брошюры с текстами законов и комментариями','2026-11-24 22:41:46','2026-11-24 22:41:46'),(5,'Радио и связь','«Радио и связь» — советское и российское научно-техническое издательство в Москве, созданное в 1981 году путём объединения издательств «Советское радио» и «Связь».\r\n\r\nОсновная информация\r\n\r\n• Год основания: 1981 (на базе издательств «Советское радио» и «Связь»)\r\n• Город: Москва\r\n• Специализация: радиотехника, электроника, связь и телекоммуникации, микропроцессоры и интегральные схемы, акустика, телевидение, программирование и справочная литература (включая переводные издания).','2026-11-24 22:46:25','2026-11-24 22:46:25'),(6,'Вече','Издательство «Вече» создано в 1991 году. Наша специализация — историко-патриотическая литература. Мы выпускаем увлекательные и разносторонние книги по истории России и мира от древних времен до наших дней. Среди наших популярных серий — «100 великих», «Военные мемуары», «Военные тайны XX века», «Неведомая Русь».\r\n\r\nЗначительную часть репертуара составляет художественная литература. Это русская и зарубежная классика, приключенческие и исторические романы, в том числе посвященные отдельным регионам России, а также современная проза. Среди полюбившихся читателям серий — «Сибириада», «Военные приключения», «Всемирная история в романах», «Мастера приключений», «Иллюстрированное собрание сочинений А. Дюма», «Военный роман», «Урал-батюшка», «Волжский роман».\r\n\r\n«Вече» издает таких известных писателей, как Валентин Пикуль, Юлия Вознесенская, Кир Булычев, Борис Васильев, Валентин Распутин, Николай Задорнов, Георгий Федосеев, а также Жюль Верн, Вальтер Скотт, Генри Райдер Хаггард. Издательство сотрудничает и с современными российскими авторами — это Александр Проханов, Владимир Крупин, Олег Рой, Михаил Щукин, Михаил Тарковский, Николай Иванов и другие. А среди историков, чьи исследования публикует «Вече», можно выделить имена Наталии Нарочницкой, Александра Мясникова Александра Боханова.','2026-11-24 22:56:23','2026-11-24 22:56:23'),(7,'Азбука','Издательство АЗБУКА — одно из крупнейших российских книжных издательств, входящее в структуру «АСТ».\r\n\r\nСтруктура и направления\r\n\r\nВ состав издательства входят четыре бренда:\r\n• «Азбука» — классика, современная проза, фантастика и фэнтези, комиксы, манга, искусство, детские книги.\r\n• «Иностранка» — переводная художественная литература и беллетристика.\r\n• «КоЛибри» — нон-фикшн: биографии, история, психология, бизнес, мемуары, кулинария.\r\n• «Махаон» — детская литература, энциклопедии и атласы.\r\n\r\nОсновные факты\r\n\r\n• История: прежнее издательство «Азбука» появилось в 1995 году в Санкт-Петербурге; в 2008 году после объединения с «Аттикус-Паблишинг» сформировалась группа «Азбука-Аттикус», позже вошедшая в структуру издательства «АСТ».\r\n• Масштаб: ежегодно выпускает более 100 книжных серий и отдельных проектов.','2026-11-24 23:42:43','2026-11-24 23:42:43'),(8,'Коми книжное издательство','Коми книжное издательство — советское и российское государственное издательство, основанное в 1920 году в Усть-Сысольске (ныне Сыктывкар) и ликвидированное в 2007 году.\r\n\r\nОсновные сведения\r\n\r\n• Направление работы: выпускало коми национальную литературу, а также научные, краеведческие и другие региональные издания.\r\n• Современные издательские площадки в регионе: сегодня выпуском книг о Республике Коми, детской и краеведческой литературы занимается, в частности, Коми республиканская типография (издательское направление создано в 1996 году, выпущено более 500 книг).\r\n• Где искать издания: архивные книги старого издательства встречаются в библиотеках, букинистических собраниях и каталогах вроде LiveLib или ОРПК, а современные книги региональных издателей — на OZON и у самих издателей в Сыктывкаре.','2026-11-25 22:44:36','2026-11-25 22:44:36'),(9,'Зенит','Издательство «Зенит» (1990-е годы) — выпускало художественную, историческую и классическую литературу','2026-11-26 22:41:01','2026-11-26 22:41:01'),(10,'Детская литература','«Детская литература» (Государственное издательство детской литературы («Детгиз») в 1933—1936 и 1941—1963 годах и «Детиздат» в 1936—1941 годах) — российское издательство. Выпускает литературу для детей младшего школьного возраста. Основано в 1933 году. В советское время располагалось в Москве по адресу Малый Черкасский переулок, дом 1.','2026-11-26 22:55:50','2026-11-26 22:55:50'),(11,'Прометей','«Прометей» — российское издательство в Москве, специализирующееся на учебной, научной и гуманитарной литературе.\r\n\r\nИстория\r\n\r\n• 1907–1916: В Санкт-Петербурге существовало первое издательство с таким названием под руководством книгоиздателя Н. Н. Михайлова. Оно выпускало художественную, философскую, историческую и справочную литературу.\r\n• 1988: Издательство было воссоздано при МГПИ им. В. И. Ленина.\r\n• 2013: Выделилось в самостоятельное юридическое лицо (ООО «Прометей») в Москве.\r\n\r\nТематика книг\r\n\r\n• Педагогика, психология и дефектология.\r\n• Лингвистика и языкознание.\r\n• История, философия, культурология и политология.\r\n• Экономика, социология и юриспруденция.\r\n• Естественные науки (физика, химия, биология, медицина).','2026-11-26 23:09:11','2026-11-26 23:09:11');
