INSERT INTO `series` VALUES (1,'Азбука-классика / Non-fiction','«Азбука-классика. Non-Fiction» — карманная книжная серия издательства «Азбука». В ней выходят нехудожественные тексты: философия, история, психология, культурология, мемуары и научно-популярные работы в мягкой обложке.','2026-11-24 23:45:11','2026-11-24 23:45:11');
