INSERT INTO `tags` VALUES (1,'Боевые искусства','2026-11-24 22:08:09','2026-11-24 22:08:09','Боевые искусства — это системы техник и традиций ведения боя, самозащиты и физического или духовного развития. Они включают как спортивные единоборства, так и прикладные или традиционные школы.'),(2,'Фантастика','2026-11-24 22:31:25','2026-11-24 22:31:25','Это жанр, творческий метод и область искусства (литературы, кино, игр, живописи), в основе которых лежит фантастическое допущение и нарушение границ привычной реальности.'),(3,'Эзотерика','2026-11-24 22:40:07','2026-11-24 22:40:07','Эзотерика (или эзотеризм) — это совокупность мистических, символических и духовных учений и практик, которые опираются на «скрытое» или внутреннее знание, недоступное непосвящённым или не требующее научной проверки. Слово происходит от древнегреческого esoterikos — «внутренний».'),(4,'История авиации','2026-11-24 23:01:31','2026-11-24 23:01:31',''),(5,'История','2026-11-24 23:48:07','2026-11-24 23:48:07','История — это наука и область знания о прошлом человечества, а также сам процесс развития общества и рассказа о произошедших событиях. Слово восходит к древнегреческому ἱστορία («расспрашивание», «исследование»).'),(6,'Религия','2026-11-24 23:48:33','2026-11-24 23:48:33','Религия — это система взглядов, убеждений и практик, основанная на вере в сверхъестественное, высшие силы или божественное начало и включающая моральные нормы, обряды и религиозные организации.'),(7,'Литературный сказ','2026-11-26 22:45:01','2026-11-26 22:45:01','Литературный сказ — это приём художественного повествования или особый жанр прозы, при котором текст стилизован под устный рассказ конкретного персонажа с живой разговорной или просторечной речью.\r\nВ литературоведении словосочетание «литературный сказ» часто пересекается с двумя понятиями: сказом как формой повествования и литературной сказкой как авторским жанром.'),(8,'Реалистическая проза о взрослении','2026-11-26 22:57:30','2026-11-26 22:57:30','Реалистическая проза о взрослении — это художественные произведения, в которых становление личности героя показано без фантастики и мистики, через реальные жизненные испытания, психологические конфликты и столкновение с миром взрослых.'),(9,'Социально-психологическая драма','2026-11-26 22:58:11','2026-11-26 22:58:11','Социально-психологическая драма — это жанр литературы, театра и кино, в котором внутренние переживания и изменения личности героя тесно связаны с влиянием общества, социальных норм и среды'),(10,'Научная фантастика','2026-11-26 22:58:55','2026-11-26 22:58:55','Научная фантастика — жанр искусства и литературы, где сюжет строится на допущениях в области науки, технологий или общества и исследует их влияние на человека и мир. Действие часто происходит в будущем, космосе, альтернативной истории или в мире с новыми технологиями.'),(11,'Мемуары','2026-11-26 23:13:28','2026-11-26 23:13:28','Мемуары — это жанр документальной литературы, в котором автор рассказывает о прошлых событиях и людях, опираясь на собственный опыт и память.');
/*!40000 ALTER TABLE `tags` ENABLE KEYS */;
UNLOCK TABLES;

